  cylinder(name+' stem',(x,y,z),(xx,yy,zz),.025,wood['frame'],6)
  # Low designed leaf sprays, not opaque foliage spheres.
  for k in range(7):
   a=ang+k*.9;start=Vector((xx,yy,zz));end=start+Vector((math.cos(a)*s*.5,math.sin(a)*s*.5,s*.22));side=Vector((-math.sin(a),math.cos(a),0))*s*.15
   mesh(name+' leaf',[start,(start+end)/2+side,end,(start+end)/2-side,(start+end)/2+Vector((0,0,.045))],[(0,1,4),(1,2,4),(2,3,4),(3,0,4)],leaf if k%2 else leaf2)

